import{_ as i,a0 as u,w as l,s,ao as d,I as e,a1 as n,A as a,x as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Fedora Linux 的各种版本 | LCTT x X-CMD","titleTemplate":false,"description":"Fedora Linux 的各种版本 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Fedora Linux 的各种版本 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Fedora Linux 的各种版本 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20211203 Introduce the different Fedora Linux editions","title":"Fedora Linux 的各种版本","tag":"202209","desc":""},"relativePath":"202209/20211203 Introduce the different Fedora Linux editions.md","filePath":"[post].md"}'),p={name:"202209/20211203 Introduce the different Fedora Linux editions.md"};function f(F,r,m,x,b,g){const o=u("Link");return l(),s("div",null,[r[24]||(r[24]=d('<h1 id="fedora-linux-的各种版本" tabindex="-1">Fedora Linux 的各种版本 <a class="header-anchor" href="#fedora-linux-的各种版本" aria-label="Permalink to “Fedora Linux 的各种版本”">​</a></h1><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/11/FedoraMagz-FedoraEditions-Intro-816x345.png" alt="Introduce the differenct Fedora Linux editions"></p><p>我们在使用 Fedora Linux 时有不同的偏好。例如，有些人选择 Fedora Linux，是因为 Fedora Workstation 默认使用 GNOME 作为其桌面环境。但也有一些人想使用 Fedora Linux 但想使用不同的桌面环境。或者也有一些人使用 Fedora Linux 有特定的需求，但不想被系统配置和应用安装所困扰。甚至有些人想根据自己的需要自由安装 Fedora Linux。因此 Fedora Linux 根据你的需要提供了多个版本。本文将介绍不同的 Fedora Linux 版本。</p><h3 id="fedora-官方版本" tabindex="-1">Fedora 官方版本 <a class="header-anchor" href="#fedora-官方版本" aria-label="Permalink to “Fedora 官方版本”">​</a></h3><p>我们从 Fedora Linux 的 <ruby>官方版本<rt>Edition</rt></ruby> 开始，即 Fedora Workstation、Fedora Server 和 Fedora IoT。 Fedora Workstation 是 Fedora Linux 的官方版本，可以安装在笔记本电脑和台式电脑上。此版本附带 GNOME 作为默认桌面环境和各种标准应用，因此 Fedora Linux 已为日常使用做好准备。而 Fedora Server 专门用于服务器用途，提供邮件服务器、DNS 等的安装。最后一个是 Fedora IoT，用于物联网和边缘设备生态系统。</p><p>在 Fedora 项目网站主页上，你可以找到另外两个版本：Fedora CoreOS 和 Fedora Silverblue。Fedora CoreOS 是一个自动更新的操作系统，旨在安全、大规模地运行容器化工作负载。而 Fedora Silverblue 是一个不可变的桌面操作系统，旨在支持以容器为中心的工作流。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/11/g-monitor-overview.png" alt="Introduce the different Fedora Linux editions: Fedora Workstation"></p><p>更多信息可在此链接获得：</p>',8)),e("blockquote",null,[e("p",null,[e("strong",null,[n(o,{href:"https://getfedora.org/"},{default:a(()=>[...r[0]||(r[0]=[t("https://getfedora.org/",-1)])]),_:1})])])]),r[25]||(r[25]=e("h3",{id:"fedora-定制版-可选桌面",tabindex:"-1"},[t("Fedora 定制版：可选桌面 "),e("a",{class:"header-anchor",href:"#fedora-定制版-可选桌面","aria-label":"Permalink to “Fedora 定制版：可选桌面”"},"​")],-1)),r[26]||(r[26]=e("p",null,[t("Fedora "),e("ruby",null,[t("定制版"),e("rt",null,"Spin")]),t(" 很受那些非常在意桌面外观的人的欢迎。大多数人都知道 Fedora Linux 只有 GNOME 作为默认桌面环境。即使你真的想使用 GNOME 以外的桌面环境，也有几个替代桌面选项。使用 Fedora 定制版，你可以在安装 Fedora Linux 时立即获得你最喜欢的桌面环境。你可以从 KDE Plasma、XFCE、LXQt、MATE、Cinnamon、LXDE 和 SoaS 中进行选择。此外，对于喜欢平铺窗口管理器的人，Fedora Linux 还提供了 Fedora i3 定制版，其中 i3 作为默认窗口管理器，并附带了几个标准应用。")],-1)),r[27]||(r[27]=e("p",null,[e("img",{src:"https://fedoramagazine.org/wp-content/uploads/2021/11/screenshot-kde-1024x640.jpg",alt:"Introduce the different Fedora Linux editions: Fedora Plasma"})],-1)),r[28]||(r[28]=e("p",null,[e("img",{src:"https://fedoramagazine.org/wp-content/uploads/2021/11/screenshot-cinnamon-1024x576.jpg",alt:"Introduce the different Fedora Linux editions: Fedora Cinnamon"})],-1)),r[29]||(r[29]=e("p",null,"更多信息可在此链接获得：",-1)),e("blockquote",null,[e("p",null,[e("strong",null,[n(o,{href:"https://spins.fedoraproject.org/"},{default:a(()=>[...r[1]||(r[1]=[t("https://spins.fedoraproject.org/",-1)])]),_:1})])])]),r[30]||(r[30]=d('<h3 id="fedora-实验室-功能包" tabindex="-1">Fedora 实验室：功能包 <a class="header-anchor" href="#fedora-实验室-功能包" aria-label="Permalink to “Fedora 实验室：功能包”">​</a></h3><p>Fedora <ruby>实验室<rt>Lab</rt></ruby> 是根据特定需求打包的 Fedora Linux 软件包集合。因此，这些版本的安装包都根据其功能提供了应用和必要的内容。Fedora 实验室提供多种软件包选择，例如<ruby>天文学<rt>Astronomy</rt></ruby>、<ruby>计算神经学<rt>Comp Neuro</rt></ruby>、<ruby>设计套件<rt>Design Suite</rt></ruby>、<ruby>游戏<rt>Games</rt></ruby>、JAM、<ruby>Python 教室<rt>Python Classroom</rt></ruby>、<ruby>安全实验室<rt>Security Lab</rt></ruby>、<ruby>机器人套件<rt>Robotics Suite</rt></ruby> 和 <ruby>科学<rt>Scientific</rt></ruby>。如果你想使用 Fedora Linux 进行设计工作，那么设计套件是你的正确选择。但是如果你喜欢玩游戏，你可以选择游戏版。</p><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/11/Fedora-Design-1024x792.png" alt="Introduce the different Fedora Linux editions: Fedora Design Suite"></p><p><img src="https://fedoramagazine.org/wp-content/uploads/2021/11/Fedora-Games-1024x792.png" alt="Introduce the different Fedora Linux editions: Fedora Games"></p><p>更多信息可在此链接获得：</p>',5)),e("blockquote",null,[e("p",null,[e("strong",null,[n(o,{href:"https://labs.fedoraproject.org/"},{default:a(()=>[...r[2]||(r[2]=[t("https://labs.fedoraproject.org/",-1)])]),_:1})])])]),r[31]||(r[31]=d('<h3 id="fedora-的其它下载" tabindex="-1">Fedora 的其它下载 <a class="header-anchor" href="#fedora-的其它下载" aria-label="Permalink to “Fedora 的其它下载”">​</a></h3><p>Fedora 的<ruby>其它下载<rt>Alt Download</rt></ruby> 集合了特定目的的可选 Fedora Linux 安装程序，例如用于测试或用于特定架构。还有其他可选格式，例如网络安装程序或种子下载等格式。在这里你可以找到<ruby>网络安装程序<rt>Network Installer</rt></ruby>、<ruby>种子下载<rt>Torrent Downloads</rt></ruby>、<ruby>可选架构<rt>Alternative Architectures</rt></ruby>、<ruby>云基础镜像<rt>Cloud Base Images</rt></ruby>、<ruby>所有内容<rt>Everything</rt></ruby>、<ruby>测试镜像<rt>Testing Images</rt></ruby> 和 Rawhide。</p><p>更多信息可在此链接获得：</p>',3)),e("blockquote",null,[e("p",null,[e("strong",null,[n(o,{href:"https://alt.fedoraproject.org/"},{default:a(()=>[...r[3]||(r[3]=[t("https://alt.fedoraproject.org/",-1)])]),_:1})])])]),r[32]||(r[32]=e("h3",{id:"总结",tabindex:"-1"},[t("总结 "),e("a",{class:"header-anchor",href:"#总结","aria-label":"Permalink to “总结”"},"​")],-1)),r[33]||(r[33]=e("p",null,"你可以自由选择适合你偏好的 Fedora Linux 版本，而不是官方版本。但是，如果你想获得具有各种桌面外观的 Fedora Linux，那么 Fedora 定制版适合你。如果你希望 Fedora Linux 根据你的需要包含应用和软件包，你可以选择 Fedora 实验室。但是，如果你是专家并且想要更自由地安装 Fedora Linux，你可以在 Fedora 其它下载处浏览替代选项。希望本文可以帮助你选择合适的 Fedora Linux，并请在评论中分享你使用 Fedora Linux 的经验。",-1)),e("p",null,[r[6]||(r[6]=t("（题图由 ",-1)),n(o,{href:"https://unsplash.com/@fredericp?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:a(()=>[...r[4]||(r[4]=[t("Frédéric Perez",-1)])]),_:1}),r[7]||(r[7]=t(" 发布在 ",-1)),n(o,{href:"https://unsplash.com/s/photos/blue-abstract?utm_source=unsplash&utm_medium=referral&utm_content=creditCopyText"},{default:a(()=>[...r[5]||(r[5]=[t("Unsplash",-1)])]),_:1}),r[8]||(r[8]=t("）",-1))]),r[34]||(r[34]=e("hr",null,null,-1)),e("p",null,[r[10]||(r[10]=t("via: ",-1)),n(o,{href:"https://fedoramagazine.org/introduce-the-different-fedora-linux-editions/"},{default:a(()=>[...r[9]||(r[9]=[t("https://fedoramagazine.org/introduce-the-different-fedora-linux-editions/",-1)])]),_:1})]),e("p",null,[r[15]||(r[15]=t("作者：",-1)),n(o,{href:"https://fedoramagazine.org/author/armanwu/"},{default:a(()=>[...r[11]||(r[11]=[t("Arman Arisman",-1)])]),_:1}),r[16]||(r[16]=t(" 选题：",-1)),n(o,{href:"https://github.com/lkxed"},{default:a(()=>[...r[12]||(r[12]=[t("lkxed",-1)])]),_:1}),r[17]||(r[17]=t(" 译者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:a(()=>[...r[13]||(r[13]=[t("geekpi",-1)])]),_:1}),r[18]||(r[18]=t(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:a(()=>[...r[14]||(r[14]=[t("wxy",-1)])]),_:1})]),e("p",null,[r[21]||(r[21]=t("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...r[19]||(r[19]=[t("LCTT",-1)])]),_:1}),r[22]||(r[22]=t(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:a(()=>[...r[20]||(r[20]=[t("Linux中国",-1)])]),_:1}),r[23]||(r[23]=t(" 荣誉推出",-1))])])}const h=i(p,[["render",f]]);export{T as __pageData,h as default};
